// Sunucu tarafı: cevapları (nokta, ipucu2) içerir; istemci modülünden içe aktarılmaz.
export const mekanBilmeceleri = (mekanId: string): KonumBilmecesi[] => KONUM_BILMECELERI.filter((b) => b.mekanId === mekanId);
